-- Migracion de clientes, deudas y abonos para Materiales / Degollado Lopar / branch_id = 1
-- Fuente: clientes.sql, ventas.sql, abonos.sql
-- Reemplaza la cartera actual de la sucursal y migra a credit_customers, credit_notes y credit_payments.

begin;

-- Tablas temporales de staging
create temporary table tmp_legacy_customers (
  customer_key integer primary key,
  name text not null,
  phone text null,
  address text null,
  credit_limit numeric not null,
  default_credit_days integer not null,
  is_active boolean not null,
  notes text null
) on commit drop;

create temporary table tmp_legacy_sales (
  sale_key integer primary key,
  customer_key integer not null,
  folio text not null,
  issue_date date not null,
  due_date date null,
  total numeric not null,
  balance numeric not null,
  paid_amount numeric not null,
  credit_days_applied integer not null,
  notes text null
) on commit drop;

create temporary table tmp_legacy_payments (
  payment_key integer primary key,
  sale_key integer not null,
  paid_at timestamptz not null,
  amount numeric not null,
  method text not null,
  reference text null,
  notes text null
) on commit drop;

