-- Validaciones basicas previas
do $$
declare missing_sales integer;
begin
  select count(*) into missing_sales
  from tmp_legacy_payments p
  left join tmp_legacy_sales s on s.sale_key = p.sale_key
  where s.sale_key is null;
  if missing_sales > 0 then
    raise exception 'Hay abonos sin venta relacionada: %', missing_sales;
  end if;
end $$;

-- Limpiar cartera actual de la sucursal 1
delete from credit_payments cp
using credit_notes cn
where cp.note_id = cn.id
  and cn.branch_id = 1;

delete from credit_notes where branch_id = 1;
delete from credit_customers where branch_id = 1;

-- Mapear clientes legacy -> nuevos UUID
create temporary table tmp_customer_map (
  legacy_customer_key integer primary key,
  customer_id uuid not null
) on commit drop;

insert into tmp_customer_map (legacy_customer_key, customer_id)
select customer_key, gen_random_uuid()
from tmp_legacy_customers;

insert into credit_customers (
  id, branch_id, name, phone, address, credit_limit, default_credit_days,
  policy, allow_cash_if_blocked, late_tolerance_days, is_active
)
select
  cm.customer_id,
  1,
  c.name,
  nullif(c.phone, ''),
  nullif(c.address, ''),
  c.credit_limit,
  case when c.default_credit_days = 15 then 15 else 30 end,
  'CERO_TOLERANCIA',
  true,
  0,
  c.is_active
from tmp_legacy_customers c
join tmp_customer_map cm on cm.legacy_customer_key = c.customer_key
order by c.customer_key;

-- Mapear ventas legacy -> nuevas notas UUID
create temporary table tmp_note_map (
  legacy_sale_key integer primary key,
  note_id uuid not null
) on commit drop;

insert into tmp_note_map (legacy_sale_key, note_id)
select sale_key, gen_random_uuid()
from tmp_legacy_sales;

insert into credit_notes (
  id, branch_id, customer_id, folio, issue_date, credit_days_applied, due_date,
  total, paid_amount, balance, notes, inventory_transaction_id
)
select
  nm.note_id,
  1,
  cm.customer_id,
  'LEG-' || s.sale_key::text,
  s.issue_date,
  case when s.credit_days_applied = 15 then 15 else 30 end,
  coalesce(s.due_date, s.issue_date + make_interval(days => case when s.credit_days_applied = 15 then 15 else 30 end)),
  s.total,
  0,
  s.total,
  coalesce(s.notes, 'Migración legacy. Folio original: ' || s.folio),
  null
from tmp_legacy_sales s
join tmp_customer_map cm on cm.legacy_customer_key = s.customer_key
join tmp_note_map nm on nm.legacy_sale_key = s.sale_key
order by s.sale_key;

-- Insertar abonos legacy
insert into credit_payments (note_id, paid_at, amount, method, reference, notes)
select
  nm.note_id,
  p.paid_at,
  p.amount,
  p.method::credit_payment_method,
  p.reference,
  p.notes
from tmp_legacy_payments p
join tmp_note_map nm on nm.legacy_sale_key = p.sale_key
order by p.payment_key;

-- Ajuste final de notas sin abonos para asegurar balance inicial
update credit_notes cn
set paid_amount = 0, balance = cn.total
where cn.branch_id = 1
  and not exists (
    select 1 from credit_payments cp where cp.note_id = cn.id
  );

-- Resumen final
select 'clientes' as tabla, count(*) as total from credit_customers where branch_id = 1
union all
select 'notas', count(*) from credit_notes where branch_id = 1
union all
select 'abonos', count(*) from credit_payments cp join credit_notes cn on cn.id = cp.note_id where cn.branch_id = 1;

commit;
